import{_ as a,o as s,c as e,a0 as n}from"./chunks/framework.CNDWyMYS.js";const k=JSON.parse('{"title":"Embedding LuaRocks in an application","description":"","frontmatter":{},"headers":[],"relativePath":"embedding_luarocks_in_an_application.md","filePath":"embedding_luarocks_in_an_application.md"}'),t={name:"embedding_luarocks_in_an_application.md"};function o(l,i,p,r,c,h){return s(),e("div",null,[...i[0]||(i[0]=[n(`<h1 id="embedding-luarocks-in-an-application" tabindex="-1">Embedding LuaRocks in an application <a class="header-anchor" href="#embedding-luarocks-in-an-application" aria-label="Permalink to &quot;Embedding LuaRocks in an application&quot;">​</a></h1><p>You can use LuaRocks bundled inside your application, for example, to install application-specific extension modules. Packaging those extensions or plugins as rocks reduces maintenance overhead and allows the user to perform updates.</p><p>In this scenario, it is not desirable to have the application-specific LuaRocks and any other copy of LuaRocks installed by the user (or other applications!) to interfere with each other. For this reason, the <code>configure</code> script allows hardcoding the location of a configuration file. For example, the compilation process of a package bundling LuaRocks could do something like this:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PREFIX</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$HOME/my-app/</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./configure</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --prefix=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PREFIX</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --sysconfdir=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PREFIX</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">/luarocks</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --force-config</span></span></code></pre></div><p>The copy of LuaRocks installed in <code>$HOME/my-app/</code> will ignore customization schemes such as the <code>$LUAROCKS_CONFIG</code> environment variable and will only use <code>$HOME/my-app/luarocks/config-5.x.lua</code>.</p><p>An interesting option in those cases is for the application to provide in its configuration file an URL for their own rocks repository, so they can have control over updates to be performed. Continuing the previous example, the config-5.x.lua file could contain something like this:</p><div class="language-lua vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">lua</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> rocks_servers </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;http://www.example.com/my-app-plugins/rocks/&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><p>This way the bundled copy of LuaRocks will download rocks from your app&#39;s plugins and not the <a href="https://luarocks.org" target="_blank" rel="noreferrer">https://luarocks.org</a> server (note that the user would still be able to override it explicitly using the <code>--server</code> flag).</p>`,8)])])}const u=a(t,[["render",o]]);export{k as __pageData,u as default};
